lessons.push(...[{"id": "reviewed-20261029-0", "title": "研究と開発", "body": "研究は新しい知識の発見を目的とする計画的な調査や探求。開発は研究成果などを具体化して、新製品や新しい生産方法の計画・設計などに役立てる活動です。", "tag": "基本", "topic": "研究開発費等", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=82", "sourceLabel": "研究開発費等に係る会計基準（定義・研究開発費の処理・ソフトウェア・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-1", "title": "研究開発費の処理", "body": "研究開発費は、原則として発生した時に費用として処理します。将来の収益を得られるか、発生時点では確実ではないためです。", "tag": "会計処理", "topic": "研究開発費等", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=82", "sourceLabel": "研究開発費等に係る会計基準（定義・研究開発費の処理・ソフトウェア・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-2", "title": "研究専用の設備", "body": "特定の研究開発にのみ使用し、他の目的に使用できない機械装置などの取得原価は、取得時の研究開発費として扱います。", "tag": "会計処理", "topic": "研究開発費等", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=82", "sourceLabel": "研究開発費等に係る会計基準（定義・研究開発費の処理・ソフトウェア・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-3", "title": "自社利用ソフトウェア", "body": "将来の収益獲得または費用削減が確実と認められる自社利用ソフトウェアの取得費用は、資産に計上し、利用期間にわたり償却します。研究開発に該当する部分は費用です。", "tag": "ソフトウェア", "topic": "研究開発費等", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=82", "sourceLabel": "研究開発費等に係る会計基準（定義・研究開発費の処理・ソフトウェア・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-4", "title": "市場販売目的の償却", "body": "資産計上した市場販売目的のソフトウェアは、見込販売数量などに基づく合理的な方法で償却します。毎期の償却額は、残存有効期間による均等配分額を下回ることはできません。", "tag": "ソフトウェア", "topic": "研究開発費等", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=82", "sourceLabel": "研究開発費等に係る会計基準（定義・研究開発費の処理・ソフトウェア・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-9", "title": "継続性の原則", "body": "会計方針を毎期みだりに変更せず、期間比較可能性を保つ。ただし、正当な理由があれば変更できる。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-10", "title": "資本取引と損益取引", "body": "資本取引から生じる剰余金と、利益から生じる剰余金を区別する。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-11", "title": "貸借対照表", "body": "一定時点の資産・負債・純資産を示し、企業の財政状態を表す。", "tag": "財務諸表", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-12", "title": "損益計算書", "body": "一定期間の収益と費用を示し、企業の経営成績を表す。", "tag": "財務諸表", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-13", "title": "流動と固定", "body": "正常営業循環基準では通常の営業活動から生じる債権・債務を流動に区分し、それ以外は原則として一年基準で区分する。", "tag": "財務諸表", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-16", "title": "先入先出法", "body": "先に受け入れたものから先に払い出されたと仮定して、払出額と期末残高を計算する。", "tag": "棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-17", "title": "移動平均法", "body": "棚卸資産を受け入れる都度、手持ちの原価と数量に今回の受入れを加え、平均単価を更新する。", "tag": "棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-18", "title": "棚卸減耗損", "body": "帳簿上の数量と実地棚卸数量の差に単位当たり取得原価を掛けて、減耗損を求める。", "tag": "棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-20", "title": "退職給付債務", "body": "従業員の勤務により生じた将来の退職給付のうち、一定の方法で当期末までに帰属する額を現在価値で算定する。", "tag": "退職給付", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-21", "title": "減損の基本", "body": "資産の収益性が低下した場合、兆候の把握、損失の認識判定、損失額の測定を行う。回収可能価額は正味売却価額と使用価値のいずれか高い額。", "tag": "固定資産", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-22", "title": "資産除去債務", "body": "有形固定資産の除去に伴う法令上または契約上の義務などを、一定の要件のもとで負債として認識する。", "tag": "固定資産", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-24", "title": "見積りの変更", "body": "新しい情報などによる会計上の見積りの変更は、変更した期間と、影響が及ぶ将来の期間に反映する。", "tag": "会計上の変更", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-25", "title": "過去の誤謬の訂正", "body": "過去の財務諸表に含まれる誤謬を訂正する場合、原則として修正再表示を行う。", "tag": "会計上の変更", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-48", "title": "売上原価の計算", "body": "期首商品棚卸高に当期商品仕入高を加え、期末商品棚卸高を控除することで、基本的な売上原価を求める。", "tag": "商品売買", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-49", "title": "総平均法", "body": "期首在庫と当期受入れの数量・原価を合計し、期間全体の平均単価を算出する方法。", "tag": "棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-50", "title": "商品評価損", "body": "収益性の低下によって、通常の販売目的で保有する棚卸資産の正味売却価額が取得原価を下回る場合、一定の方法で簿価を切り下げる。", "tag": "棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-51", "title": "定額法", "body": "取得原価から残存価額を差し引き、耐用年数にわたり均等に配分する方法。", "tag": "固定資産", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-59", "title": "引当金の計上要件", "body": "将来の特定の費用または損失で、当期以前の事象に起因し、発生の可能性が高く、金額を合理的に見積もれる場合に計上する。", "tag": "引当金", "topic": "引当金", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-66", "title": "勤務費用", "body": "勤務費用は、一期間の従業員の労働の対価として発生したと認められる退職給付を、割引計算により測定した額。", "tag": "退職給付", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-67", "title": "利息費用の計算", "body": "退職給付債務の期首残高に割引率を掛けるなどして、時の経過により発生する計算上の利息を求める。期首債務1,000万円、割引率2%なら20万円。", "tag": "退職給付", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-68", "title": "期待運用収益", "body": "期待運用収益は年金資産の運用により期待される計算上の収益。退職給付費用の算定では、一般に勤務費用・利息費用の合計から控除する。", "tag": "退職給付", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-69", "title": "数理計算上の差異", "body": "年金資産の期待運用収益と実績との差や、退職給付債務の見積数値と実績との差、見積りの変更などにより生じる。", "tag": "退職給付", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-70", "title": "正味売却価額", "body": "売価から見積追加製造原価および見積販売直接経費を控除した額。売価1,000円、追加製造費100円、販売直接経費50円なら850円。", "tag": "棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-73", "title": "減損損失の認識と測定", "body": "減損の兆候がある場合は、割引前将来キャッシュ・フローと帳簿価額を比較して認識を判定し、認識する場合は帳簿価額を回収可能価額まで減額する。", "tag": "減損", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-107", "title": "資産のグルーピング", "body": "減損の検討では、他の資産等のキャッシュ・フローからおおむね独立したキャッシュ・フローを生み出す最小単位を基本に、資産をグループ化します。", "tag": "減損", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-108", "title": "使用価値", "body": "資産または資産グループの継続使用と使用後の処分から生じる将来キャッシュ・フローを割り引いて算定した現在価値。", "tag": "減損", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-109", "title": "正味売却価額", "body": "資産または資産グループの時価から処分費用見込額を控除して算定する。時価100万円、処分費用10万円なら90万円。", "tag": "減損", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-111", "title": "真実性の原則", "body": "財政状態と経営成績を事実に即して報告するという基本原則です。見積りや選択可能な会計処理があっても、都合に合わせて事実をゆがめてよいわけではありません。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-112", "title": "正規の簿記の原則", "body": "取引を正確に記録し、その記録から財務諸表を作成するという原則です。漏れのない記録、証拠との対応、体系的な整理を確認します。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-113", "title": "明瞭性の原則", "body": "必要な会計事実を財務諸表に明瞭に表示し、利害関係者の企業状況に関する判断を誤らせないようにする原則。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-114", "title": "保守主義の原則", "body": "不利な影響が生じる可能性があるときに、慎重な判断に基づき健全な会計処理を行う。過度に保守的な処理によって真実な報告をゆがめてはならない。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-115", "title": "単一性の原則", "body": "異なる目的のために形式の異なる財務諸表を作る場合でも、その内容は信頼できる会計記録に基づき、事実の表示をゆがめてはならない。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-116", "title": "重要性の原則", "body": "重要性の乏しい項目については、財務諸表利用者の判断を誤らせない範囲で、本来の厳密な処理に代えて簡便な方法が認められることがある。", "tag": "会計原則", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-120", "title": "売上総利益", "body": "売上高から売上原価を差し引いた利益。売上高500万円、売上原価300万円なら売上総利益は200万円。", "tag": "損益計算書", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-121", "title": "営業利益", "body": "売上総利益から販売費及び一般管理費を差し引いて計算する。売上総利益200万円、販管費120万円なら営業利益は80万円。", "tag": "損益計算書", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-122", "title": "経常利益", "body": "営業利益に営業外収益を加え、営業外費用を差し引く。営業利益80万円、営業外収益5万円、営業外費用10万円なら経常利益は75万円。", "tag": "損益計算書", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-125", "title": "前払費用", "body": "すでに支払った費用のうち、翌期以降のサービスに対応する部分は前払費用として繰り越す。月1万円を12か月分支払い、当期分が3か月なら翌期分は9万円。", "tag": "決算整理", "topic": "簿記一巡", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-126", "title": "未払費用", "body": "当期に提供を受けたサービスに対応する費用で、決算時点で未払いのものを計上する。例：借方・支払利息／貸方・未払利息。", "tag": "決算整理", "topic": "簿記一巡", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-127", "title": "将来支出の現在価値", "body": "資産除去債務は、将来の除去支出を合理的に見積もり、貨幣の時間価値を反映して割り引いた現在価値で計上する。", "tag": "資産除去債務", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-128", "title": "当初計上の仕訳", "body": "資産除去債務を認識したとき、負債計上額と同額を関連する有形固定資産の帳簿価額に加える。例えば借方・建物10万円／貸方・資産除去債務10万円。", "tag": "資産除去債務", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-129", "title": "時の経過による調整", "body": "当初計上時の割引率を期首の資産除去債務残高に掛け、時の経過による調整額を算定する。期首50万円、割引率2%なら1万円。", "tag": "資産除去債務", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-130", "title": "除去費用の費用配分", "body": "有形固定資産に加えた除去費用は、その資産の減価償却を通じて残存耐用年数にわたり費用配分する。", "tag": "資産除去債務", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-131", "title": "履行差額", "body": "除去義務の履行時に、実際の支払額と債務残高に差がある場合、その差額を履行差額として処理する。", "tag": "資産除去債務", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-132", "title": "売価還元法", "body": "期末商品の売価合計額に原価率を掛けて期末棚卸資産の価額を求める方法。多くの品目を扱う場合などに用いられる。", "tag": "棚卸資産", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-213", "title": "貸借対照表の総額表示", "body": "資産・負債・純資産は原則として総額で表示し、資産と負債を相殺して省略しません。個別の会計基準などに定められた表示方法がある場合は、その規定を確認します。", "tag": "貸借対照表・表示", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-216", "title": "長期保有する棚卸資産", "body": "通常の営業活動で販売する棚卸資産は、長期間保有していても原則として流動資産に分類します。単に保有期間が長いという理由だけで固定資産にはしません。", "tag": "貸借対照表・流動固定", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-217", "title": "残存耐用年数が短い固定資産", "body": "事業に使用する固定資産は、残存耐用年数が1年以下になっても、それだけで流動資産に振り替えるわけではありません。", "tag": "貸借対照表・流動固定", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-218", "title": "営業循環と一年基準", "body": "通常の営業取引から生じる債権・債務は、正常営業循環基準を優先して流動に分類します。それ以外の債権・債務などは、原則として一年基準を検討します。", "tag": "貸借対照表・流動固定", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-219", "title": "取得原価を基礎とする考え方", "body": "資産の取得に要した対価などを基礎として帳簿に記録する考え方です。取引の証拠に基づき検証しやすい一方、帳簿価額が現在の市場価格と異なることがあります。資産の種類に応じて別の評価方法も適用されます。", "tag": "資産評価・基本", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-220", "title": "費用配分", "body": "複数の期間に役立つ資産の取得原価を、その利用に応じて各期間の費用に配分します。固定資産の減価償却はその例です。", "tag": "資産評価・基本", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-228", "title": "重要性の判断と簡便処理", "body": "重要性が乏しい消耗品について、財務諸表利用者の判断を誤らせない範囲で、買入時または払出時に費用処理する簡便な方法が認められることがあります。", "tag": "会計原則・重要性", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-229", "title": "重要性と財務諸表の表示", "body": "重要性の原則は会計処理だけでなく、財務諸表の表示にも関係します。簡便な取扱いの可否は、金額や性質が利用者の判断に及ぼす影響を考えて判断します。", "tag": "会計原則・重要性", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-267", "title": "固定資産の取得原価", "body": "購入した固定資産の取得原価には、購入代金のほか、資産を使用できる状態にするために直接要した費用などを含めます。個別の費用が該当するか条件を確認します。", "tag": "固定資産・取得", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-269", "title": "土地と減価償却", "body": "通常の土地は、建物や機械のように時の経過や使用によって価値が減少するものではないため、原則として減価償却しません。減損などの検討は別です。", "tag": "固定資産・取得", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-274", "title": "耐用年数の見積変更", "body": "固定資産の耐用年数を新たな情報に基づいて見直した場合、会計上の見積りの変更として、変更した期と影響が及ぶ将来の期間に反映します。", "tag": "固定資産・耐用年数", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-287", "title": "除去に含まれる処分", "body": "資産除去債務でいう有形固定資産の除去には、売却、廃棄、リサイクルなどによる処分が含まれます。", "tag": "資産除去債務・基礎", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-288", "title": "用途変更と遊休", "body": "固定資産の転用や用途変更、一時的な遊休状態は、資産除去債務の基準でいう除去には該当しません。", "tag": "資産除去債務・基礎", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-289", "title": "除去費用の見積り", "body": "除去に係る将来支出の見積りでは、直接の除去作業だけでなく、処分までの保管・管理に必要な支出なども考慮します。", "tag": "資産除去債務・基礎", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-291", "title": "使用に応じて生じる除去債務", "body": "設備の稼働に伴って汚染が生じるなど、使用の都度除去の義務が発生する場合、各期に発生した義務を見積もり、資産除去債務と対応する除去費用を計上します。", "tag": "資産除去債務・使用の都度", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-292", "title": "除去費用の配分", "body": "使用に応じて発生し資産計上した除去費用は、関連する固定資産の残存耐用年数にわたり配分する方法などがあります。適用する方法と問題の条件を確認します。", "tag": "資産除去債務・使用の都度", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-293", "title": "同一期に費用処理する取扱い", "body": "使用の都度発生した除去費用をいったん資産に計上し、その計上と同じ期間に同額を費用処理する取扱いも認められます。", "tag": "資産除去債務・使用の都度", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-294", "title": "個別法", "body": "取得原価の異なる品物を個別に識別し、それぞれの実際の取得原価に基づいて払出額や期末棚卸額を算定する方法です。", "tag": "棚卸資産・原価計算", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-296", "title": "継続記録法と棚卸減耗", "body": "継続記録法では受入れと払出しを記録して帳簿上の期末数量を求めます。実地棚卸数量との差を確認することで、棚卸減耗の把握につながります。", "tag": "棚卸資産・数量計算", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-298", "title": "総平均法と移動平均法の違い", "body": "総平均法は一定期間の受入れをまとめて平均単価を計算します。移動平均法は受入れの都度、手持ちと新たな受入れを合わせて平均単価を計算します。", "tag": "棚卸資産・平均法", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-301", "title": "減損の兆候とは", "body": "減損が生じている可能性を示す事象を減損の兆候といいます。兆候があれば、次に減損損失を認識するか判定します。兆候があるだけで損失額が決まるわけではありません。", "tag": "減損・兆候", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-302", "title": "営業活動の損益・キャッシュフロー", "body": "資産や資産グループを使用する営業活動の損益またはキャッシュフローが継続してマイナスとなる場合や、その見込みがある場合は、減損の兆候となり得ます。", "tag": "減損・兆候", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-303", "title": "経営環境の悪化と市場価格", "body": "事業に関連する経営環境の著しい悪化や、資産の市場価格の著しい下落は、減損の兆候となり得ます。個々の状況を踏まえて判断します。", "tag": "減損・兆候", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）", "reviewed": "2026-10-29"}, {"id": "reviewed-20261029-310", "title": "原価計算の目的", "body": "原価計算は、財務報告に必要な原価の算定や、価格設定、原価管理、予算管理などに役立つ情報を用意するために行います。", "tag": "追加・総論", "topic": "工原：総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "原価計算基準（1・原価計算の目的）", "reviewed": "2026-10-29"}]);
qs.push(...[{"q": "継続性の原則が守ろうとするものは？", "a": ["期間比較可能性", "常に同額の利益", "現金残高の一定化"], "correct": 0, "ex": "会計方針を毎期みだりに変更せず、期間比較可能性を保つ。ただし、正当な理由があれば変更できる。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）"}, {"q": "資本取引・損益取引区分の原則が求めるものは？", "a": ["資本剰余金と利益剰余金の区分", "全取引を同じ勘定に記録", "収益と現金を同額にする"], "correct": 0, "ex": "資本取引から生じる剰余金と、利益から生じる剰余金を区別する。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "貸借対照表が表すものは？", "a": ["一定時点の財政状態", "一定期間の売上だけ", "翌年度の予算"], "correct": 0, "ex": "一定時点の資産・負債・純資産を示し、企業の財政状態を表す。", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "損益計算書が表すものは？", "a": ["一定期間の経営成績", "一定時点の資産だけ", "株主名簿"], "correct": 0, "ex": "一定期間の収益と費用を示し、企業の経営成績を表す。", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "通常の営業取引から生じる売掛金の区分に用いる基準は？", "a": ["正常営業循環基準", "常に固定資産とする基準", "売上総利益率"], "correct": 0, "ex": "正常営業循環基準では通常の営業活動から生じる債権・債務を流動に区分し、それ以外は原則として一年基準で区分する。", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "先入先出法の仮定は？", "a": ["先に受け入れたものを先に払出す", "最も高価なものを先に払出す", "すべて同時に払出す"], "correct": 0, "ex": "先に受け入れたものから先に払い出されたと仮定して、払出額と期末残高を計算する。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "移動平均法で平均単価を更新するタイミングは？", "a": ["受入れの都度", "決算日に一度だけ", "売却のたびに必ず"], "correct": 0, "ex": "棚卸資産を受け入れる都度、手持ちの原価と数量に今回の受入れを加え、平均単価を更新する。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "帳簿100個、実地95個、単価200円の棚卸減耗損は？", "a": ["1,000円", "200円", "19,000円"], "correct": 0, "ex": "帳簿上の数量と実地棚卸数量の差に単位当たり取得原価を掛けて、減耗損を求める。 計算：数量差5個×200円＝1,000円。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "退職給付債務の算定で用いる考え方は？", "a": ["将来給付の現在価値", "売上高の全額", "現金預金の残高"], "correct": 0, "ex": "従業員の勤務により生じた将来の退職給付のうち、一定の方法で当期末までに帰属する額を現在価値で算定する。", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）"}, {"q": "減損の測定で使う回収可能価額は？", "a": ["正味売却価額と使用価値の高い方", "両者の低い方", "取得原価の2倍"], "correct": 0, "ex": "資産の収益性が低下した場合、兆候の把握、損失の認識判定、損失額の測定を行う。回収可能価額は正味売却価額と使用価値のいずれか高い額。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "資産除去債務に該当しうるものは？", "a": ["設備の撤去に伴う法令上の義務", "将来の売上目標", "予定配当金の見込み"], "correct": 0, "ex": "有形固定資産の除去に伴う法令上または契約上の義務などを、一定の要件のもとで負債として認識する。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "会計上の見積りの変更の影響は原則どこに反映する？", "a": ["変更期と影響が及ぶ将来期間", "必ず過去すべての期間", "どの期間にも反映しない"], "correct": 0, "ex": "新しい情報などによる会計上の見積りの変更は、変更した期間と、影響が及ぶ将来の期間に反映する。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）"}, {"q": "過去の誤謬を訂正する際の原則的な対応は？", "a": ["修正再表示", "将来の見積り変更のみ", "記録せず放置"], "correct": 0, "ex": "過去の財務諸表に含まれる誤謬を訂正する場合、原則として修正再表示を行う。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）"}, {"q": "期首20万円、当期仕入80万円、期末30万円の売上原価は？", "a": ["70万円", "100万円", "50万円"], "correct": 0, "ex": "期首商品棚卸高に当期商品仕入高を加え、期末商品棚卸高を控除することで、基本的な売上原価を求める。 計算：20＋80−30＝70万円（返品・評価損などの追加調整なし）。", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "期首10個1,000円、当期10個1,400円なら総平均単価は？", "a": ["120円", "100円", "240円"], "correct": 0, "ex": "期首在庫と当期受入れの数量・原価を合計し、期間全体の平均単価を算出する方法。 計算：（1,000＋1,400）÷（10＋10）＝120円／個。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "正味売却価額が取得原価を下回る棚卸資産について検討するものは？", "a": ["簿価の切下げ", "必ず帳簿価額を引き上げる", "資本金への振替え"], "correct": 0, "ex": "収益性の低下によって、通常の販売目的で保有する棚卸資産の正味売却価額が取得原価を下回る場合、一定の方法で簿価を切り下げる。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "取得原価100万円、残存価額0円、耐用年数5年の定額法による年間償却額は？", "a": ["20万円", "5万円", "100万円"], "correct": 0, "ex": "取得原価から残存価額を差し引き、耐用年数にわたり均等に配分する方法。 計算：（100万円−0）÷5年＝20万円／年。", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "引当金の計上要件として正しいものは？", "a": ["当期以前の事象に起因し、発生の可能性が高く、金額を合理的に見積もれる", "将来費用なら発生可能性や原因を問わず計上", "金額を合理的に見積もれなくても必ず計上"], "correct": 0, "ex": "将来の特定の費用または損失で、当期以前の事象に起因し、発生の可能性が高く、金額を合理的に見積もれる場合に計上する。", "topic": "引当金", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "勤務費用が表すものは？", "a": ["一期間の労働の対価として発生した退職給付", "現金預金の期末残高", "会社が当期に支払った配当"], "correct": 0, "ex": "勤務費用は、一期間の従業員の労働の対価として発生したと認められる退職給付を、割引計算により測定した額。", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）"}, {"q": "期首退職給付債務1,000万円、割引率2%の利息費用は？", "a": ["20万円", "2万円", "200万円"], "correct": 0, "ex": "退職給付債務の期首残高に割引率を掛けるなどして、時の経過により発生する計算上の利息を求める。期首債務1,000万円、割引率2%なら20万円。", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）"}, {"q": "退職給付費用の算定で期待運用収益は原則どう扱う？", "a": ["費用の計算から控除", "必ず費用に加算", "現金の残高に直接加算"], "correct": 0, "ex": "期待運用収益は年金資産の運用により期待される計算上の収益。退職給付費用の算定では、一般に勤務費用・利息費用の合計から控除する。", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）"}, {"q": "数理計算上の差異が生じる例は？", "a": ["期待運用収益と実際の運用成果が異なる", "商品売価が変わらない", "株主総会の開催"], "correct": 0, "ex": "年金資産の期待運用収益と実績との差や、退職給付債務の見積数値と実績との差、見積りの変更などにより生じる。", "topic": "退職給付会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=113", "sourceLabel": "退職給付に関する会計基準（6～11項・13～24項）"}, {"q": "売価1,000円、追加製造費100円、販売直接経費50円の正味売却価額は？", "a": ["850円", "950円", "1,150円"], "correct": 0, "ex": "売価から見積追加製造原価および見積販売直接経費を控除した額。売価1,000円、追加製造費100円、販売直接経費50円なら850円。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "減損損失の認識判定で比較するキャッシュ・フローは？", "a": ["割引前将来キャッシュ・フロー", "当期売上高だけ", "配当金のみ"], "correct": 0, "ex": "減損の兆候がある場合は、割引前将来キャッシュ・フローと帳簿価額を比較して認識を判定し、認識する場合は帳簿価額を回収可能価額まで減額する。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "減損で資産をまとめる際の基本的な視点は？", "a": ["独立したキャッシュ・フローを生み出す単位", "資産の色が同じか", "取得日が同一かだけ"], "correct": 0, "ex": "減損の検討では、他の資産等のキャッシュ・フローからおおむね独立したキャッシュ・フローを生み出す最小単位を基本に、資産をグループ化します。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "使用価値の計算で用いるものは？", "a": ["継続使用と処分からの将来キャッシュ・フローの現在価値", "取得時の仕入伝票のみ", "株主の人数"], "correct": 0, "ex": "資産または資産グループの継続使用と使用後の処分から生じる将来キャッシュ・フローを割り引いて算定した現在価値。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "時価100万円、処分費用10万円の正味売却価額は？", "a": ["90万円", "110万円", "10万円"], "correct": 0, "ex": "資産または資産グループの時価から処分費用見込額を控除して算定する。時価100万円、処分費用10万円なら90万円。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "真実性の原則が求めるものは？", "a": ["財政状態と経営成績の真実な報告", "常に利益を最大に見せること", "現金取引だけを記録すること"], "correct": 0, "ex": "財政状態と経営成績を事実に即して報告するという基本原則です。見積りや選択可能な会計処理があっても、都合に合わせて事実をゆがめてよいわけではありません。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "正規の簿記の原則で重視するものは？", "a": ["取引の網羅性と検証可能性", "都合の悪い取引の除外", "証拠のない任意の記録"], "correct": 0, "ex": "取引を正確に記録し、その記録から財務諸表を作成するという原則です。漏れのない記録、証拠との対応、体系的な整理を確認します。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "明瞭性の原則の目的は？", "a": ["必要な会計事実を分かりやすく表示する", "重要な負債を表示しない", "利益を一定額に固定する"], "correct": 0, "ex": "必要な会計事実を財務諸表に明瞭に表示し、利害関係者の企業状況に関する判断を誤らせないようにする原則。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "保守主義の原則の説明として適切なのは？", "a": ["慎重に判断するが、過度な処理で真実をゆがめない", "利益を必ずゼロにする", "将来の損失を根拠なく最大限計上する"], "correct": 0, "ex": "不利な影響が生じる可能性があるときに、慎重な判断に基づき健全な会計処理を行う。過度に保守的な処理によって真実な報告をゆがめてはならない。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "単一性の原則の考え方に適うものは？", "a": ["目的ごとに異なる形式でも信頼できる会計記録に基づく", "目的に応じて取引事実を改変する", "二重帳簿を作成する"], "correct": 0, "ex": "異なる目的のために形式の異なる財務諸表を作る場合でも、その内容は信頼できる会計記録に基づき、事実の表示をゆがめてはならない。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "重要性の原則による簡便処理について適切なのは？", "a": ["重要性の乏しい項目について認められることがある", "すべての重要な項目を省略できる", "必ずすべての財務情報を非表示にする"], "correct": 0, "ex": "重要性の乏しい項目については、財務諸表利用者の判断を誤らせない範囲で、本来の厳密な処理に代えて簡便な方法が認められることがある。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "売上高500万円、売上原価300万円の売上総利益は？", "a": ["200万円", "800万円", "300万円"], "correct": 0, "ex": "売上高から売上原価を差し引いた利益。売上高500万円、売上原価300万円なら売上総利益は200万円。", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "売上総利益200万円、販管費120万円の営業利益は？", "a": ["80万円", "320万円", "120万円"], "correct": 0, "ex": "売上総利益から販売費及び一般管理費を差し引いて計算する。売上総利益200万円、販管費120万円なら営業利益は80万円。", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "営業利益80万円、営業外収益5万円、営業外費用10万円の経常利益は？", "a": ["75万円", "95万円", "85万円"], "correct": 0, "ex": "営業利益に営業外収益を加え、営業外費用を差し引く。営業利益80万円、営業外収益5万円、営業外費用10万円なら経常利益は75万円。", "topic": "損益計算書", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "月1万円を12か月前払いし、当期分が3か月なら前払費用はいくら？", "a": ["9万円", "3万円", "12万円"], "correct": 0, "ex": "すでに支払った費用のうち、翌期以降のサービスに対応する部分は前払費用として繰り越す。月1万円を12か月分支払い、当期分が3か月なら翌期分は9万円。", "topic": "簿記一巡", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "当期分の支払利息が未払いの場合、決算整理で貸方に計上するものは？", "a": ["未払利息", "前払費用", "受取利息"], "correct": 0, "ex": "当期に提供を受けたサービスに対応する費用で、決算時点で未払いのものを計上する。例：借方・支払利息／貸方・未払利息。", "topic": "簿記一巡", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "将来の除去支出を負債計上する際の基本的な測定額は？", "a": ["割引現在価値", "必ず割引前の満額", "設備の売上高"], "correct": 0, "ex": "資産除去債務は、将来の除去支出を合理的に見積もり、貨幣の時間価値を反映して割り引いた現在価値で計上する。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "資産除去債務10万円を当初認識するとき、対応額を加えるものは？", "a": ["関連する有形固定資産", "売上高", "資本金"], "correct": 0, "ex": "資産除去債務を認識したとき、負債計上額と同額を関連する有形固定資産の帳簿価額に加える。例えば借方・建物10万円／貸方・資産除去債務10万円。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "期首債務50万円、当初割引率2%の時の経過による調整額は？", "a": ["1万円", "10万円", "5,000円"], "correct": 0, "ex": "当初計上時の割引率を期首の資産除去債務残高に掛け、時の経過による調整額を算定する。期首50万円、割引率2%なら1万円。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "資産除去債務に対応して資産に加えた額は通常どう費用配分する？", "a": ["関連資産の減価償却を通じて配分する", "必ず資本金へ振り替える", "決して費用にしない"], "correct": 0, "ex": "有形固定資産に加えた除去費用は、その資産の減価償却を通じて残存耐用年数にわたり費用配分する。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "除去義務履行時の実際支払額と債務残高の差は何と呼ぶ？", "a": ["履行差額", "売上原価率", "原始値入額"], "correct": 0, "ex": "除去義務の履行時に、実際の支払額と債務残高に差がある場合、その差額を履行差額として処理する。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "期末売価の合計に原価率を掛けて棚卸価額を求める方法は？", "a": ["売価還元法", "定率法", "現金主義"], "correct": 0, "ex": "期末商品の売価合計額に原価率を掛けて期末棚卸資産の価額を求める方法。多くの品目を扱う場合などに用いられる。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "貸借対照表の総額表示の原則は？", "a": ["原則として資産と負債を相殺せず表示する", "資産と負債は常に差額だけ表示する", "すべての負債を省略する"], "correct": 0, "ex": "資産・負債・純資産は原則として総額で表示し、資産と負債を相殺して省略しません。個別の会計基準などに定められた表示方法がある場合は、その規定を確認します。", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "通常販売用の商品を長期間保有する場合、原則の区分は？", "a": ["流動資産", "必ず固定資産", "必ず繰延資産"], "correct": 0, "ex": "通常の営業活動で販売する棚卸資産は、長期間保有していても原則として流動資産に分類します。単に保有期間が長いという理由だけで固定資産にはしません。", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "事業用の固定資産の残存耐用年数が1年以下になった場合は？", "a": ["それだけで流動資産に振り替えない", "必ず現金に振り替える", "必ず流動資産に振り替える"], "correct": 0, "ex": "事業に使用する固定資産は、残存耐用年数が1年以下になっても、それだけで流動資産に振り替えるわけではありません。", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "通常の営業取引から生じる債権・債務の流動・固定の区分で優先する基準は？", "a": ["正常営業循環基準", "一年基準だけ", "取得原価基準"], "correct": 0, "ex": "通常の営業取引から生じる債権・債務は、正常営業循環基準を優先して流動に分類します。それ以外の債権・債務などは、原則として一年基準を検討します。", "topic": "貸借対照表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "取得原価を基礎とする考え方の特徴として適切なのは？", "a": ["取引の証拠に基づき検証しやすい", "常に現在の市場価格と一致する", "取得時の対価を一切考慮しない"], "correct": 0, "ex": "資産の取得に要した対価などを基礎として帳簿に記録する考え方です。取引の証拠に基づき検証しやすい一方、帳簿価額が現在の市場価格と異なることがあります。資産の種類に応じて別の評価方法も適用されます。", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "複数期間に使う固定資産の取得原価を各期間に配分する例は？", "a": ["減価償却", "株式配当", "資本金の払込み"], "correct": 0, "ex": "複数の期間に役立つ資産の取得原価を、その利用に応じて各期間の費用に配分します。固定資産の減価償却はその例です。", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "重要性の乏しい消耗品に認められうる簡便な処理は？", "a": ["買入時または払出時の費用処理", "必ず資本金に計上", "取引を記録しない"], "correct": 0, "ex": "重要性が乏しい消耗品について、財務諸表利用者の判断を誤らせない範囲で、買入時または払出時に費用処理する簡便な方法が認められることがあります。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "重要性の原則の適用について適切なのは？", "a": ["処理と表示の両方に関係する", "表示には一切関係しない", "金額や性質を考慮しない"], "correct": 0, "ex": "重要性の原則は会計処理だけでなく、財務諸表の表示にも関係します。簡便な取扱いの可否は、金額や性質が利用者の判断に及ぼす影響を考えて判断します。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "固定資産の取得原価に含まれうる費用は？", "a": ["使用できる状態にするための直接費用", "翌年の一般的な広告費", "無関係な配当金"], "correct": 0, "ex": "購入した固定資産の取得原価には、購入代金のほか、資産を使用できる状態にするために直接要した費用などを含めます。個別の費用が該当するか条件を確認します。", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "通常の土地の減価償却について適切なのは？", "a": ["原則として減価償却しない", "毎期必ず定額法で償却する", "取得と同時に全額償却する"], "correct": 0, "ex": "通常の土地は、建物や機械のように時の経過や使用によって価値が減少するものではないため、原則として減価償却しません。減損などの検討は別です。", "topic": "固定資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=81", "sourceLabel": "企業会計原則・同注解（第一・一般原則／第二・損益計算書原則／第三・貸借対照表原則・注解）"}, {"q": "耐用年数の見積変更は原則どの期間に反映する？", "a": ["変更期と影響が及ぶ将来期間", "過去のすべての期間だけ", "どの期間にも反映しない"], "correct": 0, "ex": "固定資産の耐用年数を新たな情報に基づいて見直した場合、会計上の見積りの変更として、変更した期と影響が及ぶ将来の期間に反映します。", "topic": "総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=39", "sourceLabel": "会計上の変更及び誤謬の訂正に関する会計基準（4項・17項・21項）"}, {"q": "資産除去債務の基準でいう固定資産の除去に含まれるものは？", "a": ["廃棄による処分", "一時的な遊休だけ", "用途変更だけ"], "correct": 0, "ex": "資産除去債務でいう有形固定資産の除去には、売却、廃棄、リサイクルなどによる処分が含まれます。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "固定資産の単なる用途変更は、基準でいう除去に該当する？", "a": ["該当しない", "必ず該当する", "必ず売却となる"], "correct": 0, "ex": "固定資産の転用や用途変更、一時的な遊休状態は、資産除去債務の基準でいう除去には該当しません。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "除去支出の見積りで考慮しうるものは？", "a": ["処分までの保管・管理に必要な支出", "株主配当だけ", "無関係な広告費"], "correct": 0, "ex": "除去に係る将来支出の見積りでは、直接の除去作業だけでなく、処分までの保管・管理に必要な支出なども考慮します。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "設備の使用に伴い除去義務が都度発生する場合は？", "a": ["各期の発生分を見積もる", "使用開始時に必ず全額を確定する", "義務を記録しない"], "correct": 0, "ex": "設備の稼働に伴って汚染が生じるなど、使用の都度除去の義務が発生する場合、各期に発生した義務を見積もり、資産除去債務と対応する除去費用を計上します。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "使用に応じて資産計上した除去費用の配分方法として認められるものは？", "a": ["関連資産の残存耐用年数に配分する", "無期限に繰り越すだけ", "必ず売上高に計上する"], "correct": 0, "ex": "使用に応じて発生し資産計上した除去費用は、関連する固定資産の残存耐用年数にわたり配分する方法などがあります。適用する方法と問題の条件を確認します。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "使用の都度発生した除去費用を資産計上した場合に認められる取扱いは？", "a": ["同じ期間に同額を費用処理する", "資産計上が永続的に必須", "売上と相殺する"], "correct": 0, "ex": "使用の都度発生した除去費用をいったん資産に計上し、その計上と同じ期間に同額を費用処理する取扱いも認められます。", "topic": "資産除去債務", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=72", "sourceLabel": "資産除去債務に関する会計基準（3～9項・13項）"}, {"q": "品物ごとの実際の取得原価を使う方法は？", "a": ["個別法", "総平均法", "定額法"], "correct": 0, "ex": "取得原価の異なる品物を個別に識別し、それぞれの実際の取得原価に基づいて払出額や期末棚卸額を算定する方法です。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "帳簿数量と実地数量の差から棚卸減耗を把握するため、受入れと払出しを継続記録する方法は？", "a": ["継続記録法", "棚卸計算法だけ", "定率法"], "correct": 0, "ex": "継続記録法では受入れと払出しを記録して帳簿上の期末数量を求めます。実地棚卸数量との差を確認することで、棚卸減耗の把握につながります。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "受入れの都度、平均単価を更新する方法は？", "a": ["移動平均法", "総平均法", "定額法"], "correct": 0, "ex": "総平均法は一定期間の受入れをまとめて平均単価を計算します。移動平均法は受入れの都度、手持ちと新たな受入れを合わせて平均単価を計算します。", "topic": "棚卸資産", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=24", "sourceLabel": "棚卸資産の評価に関する会計基準（5項・6-2項・7項・34-1項）"}, {"q": "減損の兆候がある場合、次に行う手続きは？", "a": ["減損損失の認識判定", "必ず直ちに資産をゼロにする", "何も確認しない"], "correct": 0, "ex": "減損が生じている可能性を示す事象を減損の兆候といいます。兆候があれば、次に減損損失を認識するか判定します。兆候があるだけで損失額が決まるわけではありません。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "減損の兆候となり得る状況は？", "a": ["営業活動のキャッシュフローが継続してマイナス", "売上の一時的な増加だけ", "従業員数の確認だけ"], "correct": 0, "ex": "資産や資産グループを使用する営業活動の損益またはキャッシュフローが継続してマイナスとなる場合や、その見込みがある場合は、減損の兆候となり得ます。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "減損の兆候となり得る事象は？", "a": ["関連事業の経営環境の著しい悪化", "資産の名称変更だけ", "帳簿のページ数の増加"], "correct": 0, "ex": "事業に関連する経営環境の著しい悪化や、資産の市場価格の著しい下落は、減損の兆候となり得ます。個々の状況を踏まえて判断します。", "topic": "減損会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=83", "sourceLabel": "固定資産の減損に係る会計基準（二・減損損失の認識と測定／注解）"}, {"q": "原価計算の目的に含まれるものは？", "a": ["製品原価の算定や原価管理", "現金残高の隠蔽", "原価の記録をすべて省く"], "correct": 0, "ex": "原価計算は、財務報告に必要な原価の算定や、価格設定、原価管理、予算管理などに役立つ情報を用意するために行います。", "topic": "工原：総論", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "原価計算基準（1・原価計算の目的）"}]);
